      ],
      "dropped_pairs_from_A": ["R-89 at issue vs R-86 (R-89 in_force circular, recoded UNK)"],
      "undetermined_pairs": ["R-70 / R-95 / R-89 / R-81 as-filed (adopter none, in_force UNK)", "R-88 (adopter UNK)"]
    },
