      "status_changes": [
        {"ruling": "R-81..R-85", "from": "PREPARED", "to": "ADOPTED", "by_actor": "Decision Authority (act: R-86)", "quote": "Decision Authority confirms and adopts R-81 through R-85 without amendment."},
        {"ruling": "R-81", "from": "none stated (as filed)", "to": "PREPARED", "by_actor": "ARB Chief (provenance annotation)", "quote": "THESE FIVE ARE THEREFORE PREPARED RULINGS AWAITING ADOPTION", "note": "A mentions this change in a note but omits it from status_changes although M_chain requires every change to be attributed; it is attributable, so the condition still holds"}
      ]
    }
  },
