    },
    {
      "ruling_state": "R-95 at issue (hypothetical only)",
      "A_value": "UNK (A correctly declined the derivation)",
      "derivation": "R-86 issuer rule -> PREPARED -> NOT-IN-FORCE",
      "why_circular": "issuer -> status -> force; using it would test M_issuer / M_status on a value built from those variables",
