  ],
  "non_circular_checked": [
    {"ruling_state": "R-81..R-85 before R-86", "value": "NOT-IN-FORCE", "basis": "force language, not the marker: R-86 \"These become governing rulings effective immediately.\" (not governing before) and R-81 \"“BATCH 7 IS RELEASED” DOES NOT HOLD\""},
