  ],
  "unsupported_values": [
    {"ruling_state": "R-88 as cited by R-89", "A_value": "IN-FORCE (derived)", "problem": "rests on citation by R-89, itself PREPARED with no established force, and on 'left the PREPARED→ADOPTED mechanism in force', where 'in force' describes the mechanism, not R-88. A excludes R-60/R-66/R-72/R-76/R-79 as 'force presupposed, not stated'; R-88 is in the same position. If read as 'R-88 was adopted -> in force', the value is status-derived (circular).", "recoded": "UNK"}
  ],
  "disagreements": [
    {"id": "D1", "class": "coding", "item": "R-89 in_force", "A": "NOT-IN-FORCE (derived)", "reviewer": "UNK (circular)", "verdict_impact": "none; removes one deciding pair each from M_issuer and M_adopter, both still decided by other pairs"},
    {"id": "D2", "class": "formal reasoning", "item": "use of circular value in the test", "A": "notes flag R-89 as 'partly circular' but still use it in the M_issuer and M_adopter deciding pairs and in 'PREPARED is never in force'", "reviewer": "circular values must be recoded UNK before testing; 'PREPARED is never in force' holds only on R-81..R-85", "verdict_impact": "none"},
    {"id": "D3", "class": "source interpretation", "item": "R-88 in_force", "A": "IN-FORCE (derived from R-89's reliance and 'mechanism in force')", "reviewer": "UNK; 'in force' there modifies the mechanism, and the citing ruling is itself PREPARED; inconsistent with A's own exclusion rule", "verdict_impact": "none (R-88 has UNK issuer/status/adopter)"},
    {"id": "D4", "class": "source interpretation", "item": "R-70 issuer", "A": "\"ARB\" (header), with conflict noted", "reviewer": "human authority = Decision Authority: R-81 \"Every prior ruling R-1..R-80 was issued by the human authority\" and \"THE DECISION AUTHORITY IS THE HUMAN AUTHORITY, NOT THE CHIEF\". The header label 'ARB' is a governance track, not the issuer (R-81 carries the same 'ARB' header but was issued by the Chief)", "verdict_impact": "none (R-70 in_force UNK); adds an undetermined M_issuer pair with R-86"},
    {"id": "D5", "class": "coding", "item": "R-81 as-filed state", "A": "described in a note, not coded; its none->PREPARED change is left out of M_chain.status_changes", "reviewer": "code it: issuer ARB Chief, status none stated, adopter none, in_force UNK (self-claim \"isolation repair ACTIVE\" vs later \"“BATCH 7 IS RELEASED” DOES NOT HOLD\"); list the change, attributed to the ARB Chief", "verdict_impact": "none under UNK; see alternative reading A-1"},
